def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    # Since elements are unique, a non-decreasing sorted array means strictly increasing

    # Check if arr is already sorted non-decreasing
    def is_sorted(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    # Try all right shifts (0 to n-1)
    for shift in range(n):
        # right shift by 'shift' means last 'shift' elements come to front
        shifted = arr[-shift:] + arr[:-shift]
        if is_sorted(shifted):
            return True
    return False

def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Since elements are unique, a rotation that results in a sorted array must be a rotated sorted array.
    # We want to check if arr is a rotation of a sorted (non-decreasing) array.

    # Count how many places the order breaks (arr[i] > arr[i+1])
    breaks = 0
    for i in range(n):
        if arr[i] > arr[(i + 1) % n]:
            breaks += 1
            if breaks > 1:
                return False
    # If there is at most one break, then the array is a rotation of a sorted array.
    return True

