    if not arr:
        return True

    n = len(arr)

    # Check if arr is already non-decreasing
    def is_non_decreasing(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    if is_non_decreasing(arr):
        return True

    # Since all elements are unique, the array can be non-decreasing rotated 
    # only if the array is a rotation of a sorted strictly increasing array.
    # So, find the index of the minimal element (which should be the start of sorted array)
    min_index = arr.index(min(arr))

    # Rotate the array to the left by min_index to get candidate sorted array
    # Right shifting by k is equivalent to left shifting by n-k.
    # Here we do the left rotation to start at min element.
    rotated = arr[min_index:] + arr[:min_index]

    return is_non_decreasing(rotated)

