import re

def anti_shuffle(s):
    def sort_word(word):
        # If the word is all alphabetic, sort ascending
        if word.isalpha():
            return ''.join(sorted(word))
        # If the word contains any uppercase letter, leave as is
        if any(c.isupper() for c in word):
            return word
        # Otherwise, sort descending
        return ''.join(sorted(word, reverse=True))

    # Split by spaces, keeping spaces as tokens
    tokens = re.split(r'(\s+)', s)
    # Process only non-space tokens (words)
    result = []
    for tok in tokens:
        if tok.isspace():
            result.append(tok)
        else:
            result.append(sort_word(tok))
    return ''.join(result)

def anti_shuffle(s):
    def sort_word(word):
        # Find trailing punctuation
        idx = len(word)
        while idx > 0 and not word[idx - 1].isalnum():
            idx -= 1
        core = word[:idx]
        trailing = word[idx:]
        # Sort core characters ascending ASCII
        sorted_core = ''.join(sorted(core))
        return sorted_core + trailing

    words = s.split(' ')
    sorted_words = [sort_word(w) for w in words]
    return ' '.join(sorted_words)

def anti_shuffle(s):
    def reorder_word(word):
        # Separate trailing punctuation from the main word
        i = len(word)
        while i > 0 and not word[i-1].isalnum():
            i -= 1
        main_part = word[:i]
        punctuation = word[i:]
        if len(main_part) <= 1:
            # If main part has 0 or 1 chars, return as is with punctuation
            return main_part + punctuation
        # Determine if main_part is already sorted ascending or descending
        asc = all(main_part[j] <= main_part[j+1] for j in range(len(main_part)-1))
        desc = all(main_part[j] >= main_part[j+1] for j in range(len(main_part)-1))
        if asc or desc:
            # Return as is
            return word
        # Otherwise, sort main_part ascending
        sorted_main = ''.join(sorted(main_part))
        return sorted_main + punctuation

    # Split by spaces preserving spaces
    import re
    parts = re.split(r'(\s+)', s)
    # For each non-space part, reorder it
    for i in range(0, len(parts), 2):
        parts[i] = reorder_word(parts[i])
    return ''.join(parts)

