def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Check if already sorted
    if all(arr[i] <= arr[i+1] for i in range(n-1)):
        return True

    # Since elements are unique, find the index of the minimum element
    min_index = arr.index(min(arr))

    # Rotating the array so that min element comes to front
    rotated = arr[min_index:] + arr[:min_index]

    # Check if rotated array is sorted non-decreasingly
    return all(rotated[i] <= rotated[i+1] for i in range(n-1))

