def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    shift %= n
    if shift == 0:
        return s
    elif shift > 0:
        # shift digits left by shift
        return s[shift:] + s[:shift]
    else:
        # shift digits right by abs(shift)
        shift = -shift
        return s[-shift:] + s[:-shift]

