def find_Max(nums):
    if not nums:
        return None
    left, right = 0, len(nums) - 1
    # If array is not rotated (sorted ascending), max is last element
    if nums[left] < nums[right]:
        return nums[right]
    # Binary search for max element in rotated array
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid
    # left is index of minimum element, max is element before it (handle wrap)
    return nums[left - 1] if left > 0 else nums[-1]

