    if not arr:
        return None  # or raise an error depending on preference

    left, right = 0, len(arr) - 1

    # If array is not rotated (sorted ascending), max is last element
    if arr[left] < arr[right]:
        return arr[right]

    # Binary search for maximum in rotated sorted array
    while left < right:
        mid = (left + right) // 2
        if arr[mid] > arr[right]:
            # max is in right half including mid
            left = mid + 1
        else:
            # max is in left half excluding mid
            right = mid

    # After loop, left points to minimum element,
    # max is at left-1 (circularly)
    return arr[left - 1]

