def compute_Last_Digit(a, b):
    # If a > b, factorial(a) cannot divide factorial(b)
    if a > b:
        raise ValueError("factorial(a) does not divide factorial(b) when a > b")
    # factorial(b) // factorial(a) = product of integers from a+1 to b
    # Compute last digit of this product

    last_digit = 1
    for x in range(a + 1, b + 1):
        last_digit = (last_digit * (x % 10)) % 10

    return last_digit

