def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Handle single digit numbers:
    if num < 8:
        return num + 1

    # Check if all 9's, e.g. 9, 99, 999 -> next palindrome is 10..01
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def mirror_left_to_right(s):
        half = length // 2
        if length % 2 == 0:
            return s[:half] + s[:half][::-1]
        else:
            return s[:half+1] + s[:half][::-1]

    candidate = int(mirror_left_to_right(s))
    if candidate > num:
        return candidate

    # Otherwise increment the middle part and mirror again
    s_list = list(s)
    mid = (length - 1) // 2  # middle index for odd, left middle for even

    # Increment the middle and handle carry
    i = mid
    j = length - 1 - mid
    while i >= 0:
        if s_list[i] != '9':
            s_list[i] = str(int(s_list[i]) + 1)
            s_list[j] = s_list[i]
            break
        else:
            s_list[i] = '0'
            s_list[j] = '0'
            i -= 1
            j += 1
    else:
        # If we carried over all digits (like 999 -> 1001 handled above), no need here
        pass

    # Mirror left to right again to be sure
    half = length // 2
    if length % 2 == 0:
        for k in range(half):
            s_list[length - 1 - k] = s_list[k]
    else:
        for k in range(half):
            s_list[length - 1 - k] = s_list[k]

    return int("".join(s_list))

