def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[i][x] = number of sequences of length i with last element x
    # i ranges from 1 to n
    # x ranges from 1 to m
    if n == 1:
        return m  # any integer from 1 to m can be the first element

    dp = [0] * (m + 1)
    # Base case: sequences of length 1
    for x in range(1, m + 1):
        dp[x] = 1

    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # prefix sum to optimize counting
        prefix = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + dp[x]

        for x in range(1, m + 1):
            # previous element p must satisfy:
            # p * 2 <= x <= m
            # p <= x // 2
            max_prev = x // 2
            if max_prev >= 1:
                new_dp[x] = prefix[max_prev]
            else:
                new_dp[x] = 0
        dp = new_dp

    return sum(dp[1:])  # sum over all possible last elements

def get_total_number_of_sequences(n: int, m: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(pos: int, prev: int) -> int:
        if pos == n:
            return 1
        total = 0
        start = 2 * prev
        if start > m:
            return 0
        for next_val in range(start, m + 1):
            total += count_sequences(pos + 1, next_val)
        return total

    total_sequences = 0
    for first in range(1, m + 1):
        total_sequences += count_sequences(1, first)
    return total_sequences

