def remove_column(data, index):
    if isinstance(data, list):
        # If this list contains lists, remove the element at index from each inner list
        # and recursively process each element
        result = []
        for item in data:
            if isinstance(item, list):
                # Remove the element at the given index if it exists
                if 0 <= index < len(item):
                    new_item = item[:index] + item[index+1:]
                else:
                    new_item = item[:]
                # Recursively process the new_item's elements (in case of deeper nesting)
                result.append(remove_column(new_item, index))
            else:
                # For non-list elements, just keep them as is
                result.append(item)
        return result
    else:
        # If it's not a list, return it as is
        return data

