        if y == 0:
            return (x, 1, 0)
        g, x1, y1 = extended_gcd(y, x % y)
        return (g, y1, x1 - (x // y) * y1)

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None  # no integer solutions

    # Scale the particular solution by n//g
    x0 *= n // g
    y0 *= n // g
    return (x0, y0)

