def get_total_number_of_sequences(N: int, K: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(length, min_val):
        if length == 0:
            return 1
        total = 0
        # next element must be >= min_val and <= N
        for x in range(min_val, N + 1):
            # next min_val for subsequent element is at least double current x
            total += count_sequences(length - 1, x * 2)
        return total

    return count_sequences(K, 1)

def get_total_number_of_sequences(N: int, K: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(length, min_value):
        if length == 0:
            return 1
