        # next element must be >= min_value and <= N
        # iterate over all valid next elements
        for next_val in range(min_value, N + 1):
            # next element doubles the previous element at least
            # so next min_value for next call is next_val * 2
            total += count_sequences(length - 1, next_val * 2)
        return total

    # first element can be from 1 to N
    total_count = 0
    for start in range(1, N + 1):
        total_count += count_sequences(K - 1, start * 2)
