def get_total_number_of_sequences(N: int, K: int) -> int:
    # dp[i][x]: number of sequences of length i ending with x
    # We can optimize by storing cumulative sums to avoid O(N^2)
    # However, since each next element >= 2 * previous,
    # for dp[i][x], sum over dp[i-1][y] where y <= x//2

    dp_prev = [1] * (N + 1)  # sequences of length 1: any element 1..N
    for _ in range(2, K + 1):
        dp_curr = [0] * (N + 1)
        prefix_sum = [0] * (N + 1)
        for x in range(1, N + 1):
            prefix_sum[x] = prefix_sum[x - 1] + dp_prev[x]
        for x in range(1, N + 1):
            max_prev = x // 2
            if max_prev >= 1:
                dp_curr[x] = prefix_sum[max_prev]
            else:
                dp_curr[x] = 0
        dp_prev = dp_curr
    return sum(dp_prev[1:]) if K > 0 else 0

