def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # If num is less than 8, the next palindrome is num+1 (since single digit palindrome)
    if num < 8:
        return num + 1

    def is_all_nines(s):
        return all(ch == '9' for ch in s)

    # If all digits are 9, the next palindrome is 10...01 (length+1)
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Generate palindrome by mirroring left to right
    def make_palindrome(left, odd_length):
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    odd = (length % 2 != 0)
    mid = length // 2

    if odd:
        left = s[:mid + 1]
    else:
        left = s[:mid]

    pal_candidate = make_palindrome(left, odd)

    if pal_candidate > num:
        return pal_candidate

    # Increment the middle part and create a new palindrome
    # Convert left to int, increment, then rebuild palindrome
    left_num = int(left)
    left_num += 1
    left = str(left_num)
    # If incrementing left changes its length (e.g., 999 -> 1000), adjust palindrome length accordingly
    if len(left) > (mid + 1 if odd else mid):
        # This happens when the palindrome length increases, e.g. 999 -> 1001
        return int('1' + ('0' * (length - 1)) + '1')

    return make_palindrome(left, odd)

