def capital_words_spaces(s: str) -> str:
    # Insert space between a lowercase or non-letter and an uppercase letter
    # But only if there's no space or punctuation in between (i.e. concatenated words)
    # We look for a lowercase or uppercase letter followed immediately by uppercase letter
    # However, two uppercase letters together should be split only if the second is start of a new word,
    # so we split before uppercase letter preceded by lowercase letter or uppercase letter followed by lowercase letters.
    # The simplest approach here is to split before uppercase letters that follow lowercase letters.

    # Pattern: look for a lowercase letter followed immediately by uppercase letter
    return re.sub(r'(?<=[a-z])(?=[A-Z])', ' ', s)

